	error_reporting(0);	

	fncDirList("../Content");
	
	function fncDirList($dirPath)
		{
			print "<table cellpadding='0' cellspacing='0' width='100%'>";

			$dirList					= opendir($dirPath);  				
	
			while (($dirPart			= @readdir($dirList)) == true) 
				{  						
					if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
						{			
							$strTemp			= explode("<+>" ,file_get_contents("../Content/".$dirPart));		
							$Keyword			= stripslashes(trim($strTemp[0]));
							
							if($strTemp[5] == "")
								{
									$strTemp[5]			= "01/01/2006";
								}			
																												
							if(strtotime(date("m/d/Y")) > strtotime($strTemp[5]))
								{																																										
									$Title		= stripslashes(trim($strTemp[1]));									
									$Summary	= str_replace("  ", " ", str_replace("nbsp", "", ereg_replace("[^a-z,A-Z,0-9, ]"," ",strip_tags(stripslashes(trim($strTemp[4]))))));
											
									echo "<tr><td><p><b>\n<a href='../Articles/".str_replace(".txt", ".php", $dirPart)."'>".$Title."</a>\n</b>\n";
									echo "<br>\n<br>\n".substr($Summary, 0, 256)."<br>\n<small>\n<a href='../Articles/".str_replace(".txt", ".php", $dirPart)."'>Read More...</a>\n</small>\n<br>\n<br>\n</p></td></tr>";
											
								}
						}										
				
				} 	
			print "</table>";
		}

?>